# Ediciones Guizar - Fabrica de Videos: "La liebre y la tortuga" (Wan 2.2 en 2 T4).
# Toma el motor probado (motor-animacion/ia-kaggle/kaggle_leon_rapido.py) y solo cambia dibujos e indicaciones.
# Para otro cuento: copiar este archivo y cambiar BASE y ESCENAS (7 escenas x 2 indicaciones tranquilas).
import urllib.request, subprocess, sys, os
RAW = "https://raw.githubusercontent.com/apolobelden-sketch/videomarket-pro/main/motor-animacion/ia-kaggle/kaggle_leon_rapido.py"
NUEVO = "BASE = \"https://pnjglzuxsyahxcbgjwvq.supabase.co/storage/v1/object/public/archivos/libros/liebre-tortuga-ia/\"\nESTILO = \", gentle small movements, both characters stay fully inside the frame the whole time, same scene, fixed static camera, smooth natural character animation, Pixar style 3D children's movie, warm light\"\nNEG = \"static, frozen, blurry, distorted, deformed face, extra limbs, text, letters, words, watermark, low quality, flicker, morphing, scene change, cut, new characters, character disappears, leaving the frame, camera movement, zoom, walking backwards\"\nESCENAS = [\n (\"e1\", [\"The hare laughs and points at the tortoise, his long ears wiggle, the tortoise blinks calmly and smiles, flowers sway\",\n         \"The hare keeps giggling and holds his belly, the tortoise slowly shakes his head and smiles patiently\"]),\n (\"e2\", [\"The tortoise talks calmly and raises one finger, the hare puts his paws on his hips and raises an eyebrow\",\n         \"The hare laughs and nods, accepting the challenge, the tortoise smiles confidently, grass sways\"]),\n (\"e3\", [\"The hare runs in place with fast legs, dust puffs behind his feet, his ears flap in the wind, the flag waves\",\n         \"The hare keeps running energetically, his ears bounce, the tortoise watches and blinks, the flag waves\"]),\n (\"e4\", [\"The tortoise walks slowly and steadily forward, moving his legs one by one, smiling with determination, flowers sway\",\n         \"The tortoise keeps walking calmly step by step, he breathes and smiles, butterflies flutter nearby\"]),\n (\"e5\", [\"The hare sleeps peacefully under the tree, his chest rises and falls as he breathes, his ears twitch, leaves sway\",\n         \"The hare keeps sleeping and smiles in his sleep, his nose wiggles, leaves fall gently from the tree\"]),\n (\"e6\", [\"The tortoise walks through the red ribbon at the finish line, the ribbon bends and breaks, the animals behind clap happily\",\n         \"The tortoise raises his arms happily and smiles, the animals keep clapping and cheering, confetti falls\"]),\n (\"e7\", [\"The tortoise smiles proudly and touches his gold medal, the hare blinks surprised and scratches his head shyly\",\n         \"The hare smiles and claps for the tortoise, the tortoise nods kindly, the medal shines in the sun\"]),\n]\n"
src = urllib.request.urlopen(RAW).read().decode()
a = src.index("BASE = "); b = src.index("W, H, CUADROS")
src = src[:a] + NUEVO + src[b:]
src = src.replace('yo = "/kaggle/src/script.py"', 'yo = "/kaggle/tmp/motor.py"')
os.makedirs("/kaggle/tmp", exist_ok=True)
open("/kaggle/tmp/motor.py", "w").write(src)
open("/kaggle/working/motor_usado.txt", "w").write(src)
subprocess.run([sys.executable, "/kaggle/tmp/motor.py"])
